local CrystalGobletMaker = {}
local PRODUCTS = {
    simple_glass_goblet = { name = "Preprost steklen kelih", glassCost = 2, time = 3, cost = 40, beauty = 18, happiness = 1, description = "Preprost steklen kelih za jedilnico." },
    lead_crystal_goblet = { name = "Svinčevokristalni kelih", glassCost = 3, leadCost = 1, time = 6, cost = 130, beauty = 35, happiness = 2, prestige = 2, description = "Svinčevokristalni kelih za trgovce." },
    silver_stem_goblet = { name = "Srebrnostebelni kelih", glassCost = 3, silverCost = 1, leadCost = 1, time = 9, cost = 320, beauty = 50, happiness = 2, prestige = 6, description = "Srebrnostebelni kelih za plemiče." },
    gold_rim_goblet = { name = "Zlatookrasni kelih", glassCost = 4, goldCost = 1, silverCost = 1, leadCost = 1, time = 13, cost = 760, beauty = 65, happiness = 3, prestige = 14, description = "Zlatookrasni kelih za visoke plemiče." },
    jewel_set_goblet = { name = "Draguljasta kelih", glassCost = 4, goldCost = 2, silverCost = 1, leadCost = 1, jewelCost = 1, time = 17, cost = 1700, beauty = 80, happiness = 5, prestige = 27, description = "Kelih z draguljem za visoko plemstvo." },
    royal_grand_goblet_set = { name = "Kraljevski veliki kelihi", glassCost = 6, goldCost = 3, silverCost = 2, leadCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, beauty = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski kelihi z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    goblet_workshop = { name = "Keliška delavnica", cost = { gold = 240, wood = 100, stone = 120, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    crystal_loft = { name = "Kristalna podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, lead = 6 }, upkeep = 20, qualityBonus = 18 },
    master_glass_atelier = { name = "Mojstrski steklarsski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_goblet_palace = { name = "Kraljevska keliška palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
CrystalGobletMaker.glassStock = 18; CrystalGobletMaker.leadStock = 12; CrystalGobletMaker.silverStock = 6; CrystalGobletMaker.goldStock = 6; CrystalGobletMaker.jewelStock = 4; CrystalGobletMaker.pearlStock = 4
CrystalGobletMaker.productStock = {}; CrystalGobletMaker.buildings = {}; CrystalGobletMaker.maker = nil; CrystalGobletMaker.activeMaking = {}; CrystalGobletMaker.totalProducts = 0; CrystalGobletMaker.dayTimer = 0
function CrystalGobletMaker.init() CrystalGobletMaker.glassStock=18; CrystalGobletMaker.leadStock=12; CrystalGobletMaker.silverStock=6; CrystalGobletMaker.goldStock=6; CrystalGobletMaker.jewelStock=4; CrystalGobletMaker.pearlStock=4; CrystalGobletMaker.productStock={}; CrystalGobletMaker.buildings={}; CrystalGobletMaker.maker=nil; CrystalGobletMaker.activeMaking={}; CrystalGobletMaker.totalProducts=0; CrystalGobletMaker.dayTimer=0; print("[CrystalGobletMaker] Royal Crystal Goblet Maker System initialized (6 products, 4 buildings)") end
function CrystalGobletMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrystalGobletMaker.maker={name=n or ("Keličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Keličar najet: %s (spretnost: %d)",CrystalGobletMaker.maker.name,s),"success") end; return true end
function CrystalGobletMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrystalGobletMaker.build(id) local ok,e=CrystalGobletMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrystalGobletMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrystalGobletMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrystalGobletMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrystalGobletMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and CrystalGobletMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.leadCost and CrystalGobletMaker.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.silverCost and CrystalGobletMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrystalGobletMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrystalGobletMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrystalGobletMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrystalGobletMaker.buildings==0 then return false,"Potrebna keliška delavnica" end; if not CrystalGobletMaker.maker then return false,"Potreben keličar" end; return true end
function CrystalGobletMaker.make(pt,qty) qty=qty or 1; local ok,e=CrystalGobletMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then CrystalGobletMaker.glassStock=CrystalGobletMaker.glassStock-d.glassCost*qty end; if d.leadCost then CrystalGobletMaker.leadStock=CrystalGobletMaker.leadStock-d.leadCost*qty end; if d.silverCost then CrystalGobletMaker.silverStock=CrystalGobletMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrystalGobletMaker.goldStock=CrystalGobletMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrystalGobletMaker.jewelStock=CrystalGobletMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrystalGobletMaker.pearlStock=CrystalGobletMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrystalGobletMaker.maker then t=math.max(1,t-math.floor(CrystalGobletMaker.maker.skill/13)) end; table.insert(CrystalGobletMaker.activeMaking,{id="goblet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrystalGobletMaker.completeMaking(m) local q=1.0+(CrystalGobletMaker.getQualityBonus()/100); if CrystalGobletMaker.maker then q=q+(CrystalGobletMaker.maker.skill/150) end; q=math.min(2.4,q); CrystalGobletMaker.productStock[m.productType]=(CrystalGobletMaker.productStock[m.productType] or 0)+m.quantity; CrystalGobletMaker.totalProducts=CrystalGobletMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrystalGobletMaker.maker then CrystalGobletMaker.maker.itemsMade=CrystalGobletMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CrystalGobletMaker.maker.skill=math.min(100,CrystalGobletMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kelih izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"goblet.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function CrystalGobletMaker.update(dt) if not _G.state then return end; CrystalGobletMaker.dayTimer=CrystalGobletMaker.dayTimer+dt; if CrystalGobletMaker.dayTimer>=30 then CrystalGobletMaker.dayTimer=0; for i=#CrystalGobletMaker.activeMaking,1,-1 do local m=CrystalGobletMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrystalGobletMaker.completeMaking(m); table.remove(CrystalGobletMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrystalGobletMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrystalGobletMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrystalGobletMaker.getStats() return {glassStock=CrystalGobletMaker.glassStock,leadStock=CrystalGobletMaker.leadStock,silverStock=CrystalGobletMaker.silverStock,goldStock=CrystalGobletMaker.goldStock,jewelStock=CrystalGobletMaker.jewelStock,pearlStock=CrystalGobletMaker.pearlStock,productStock=CrystalGobletMaker.productStock,numBuildings=#CrystalGobletMaker.buildings,hasMaker=CrystalGobletMaker.maker~=nil,makerName=CrystalGobletMaker.maker and CrystalGobletMaker.maker.name or "—",makerSkill=CrystalGobletMaker.maker and CrystalGobletMaker.maker.skill or 0,activeMaking=#CrystalGobletMaker.activeMaking,totalProducts=CrystalGobletMaker.totalProducts} end
return CrystalGobletMaker
